:root {
  --card-bg: #fdf6e3;
  --card-border: #b5894a;
  --header-bg: #b5894a;
  --header-text: #fdf6e3;
  --label-text: #7a5c2e;
  --title-text: #3b2a14;
  --item-border: #d9bb85;
  --name-text: #4a3318;
  --amount-text: #7a5c2e;
  --badge-bg: #e8d5a3;
  --badge-text: #5a3e1b;
  --footer-border: #b5894a;
}

.recipe-card {
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 6px;
  width: 300px;
  overflow: hidden;
}

.card-header {
  background-color: var(--header-bg);
  padding: 10px 16px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.card-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--header-text);
  opacity: 0.8;
}

.card-title {
  font-size: 22px;
  font-weight: 700;
  color: var(--header-text);
  margin: 0;
  line-height: 1.1;
}

.card-body {
  padding: 12px 16px;
}

.ingredient-list {
  list-style: none;
  margin: 0 0 12px 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.ingredient-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 0;
  border-bottom: 1px dashed var(--item-border);
}

.ingredient-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--name-text);
}

.ingredient-amount {
  font-size: 13px;
  color: var(--amount-text);
  font-weight: 500;
}

.card-footer {
  display: flex;
  gap: 8px;
  padding-top: 10px;
  border-top: 1px solid var(--footer-border);
}

.temp-badge,
.yield-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: 4px;
  letter-spacing: 0.5px;
}
